package com.bank.apigateway.config; import org.springframework.context.annotation.*; import org.springframework.security.config.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.*; @Configuration public class SecurityConfig{@Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception{http.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).httpBasic(Customizer.withDefaults()); return http.build();}}